public static class PostTitleUpdater
{
    public static async Task<bool> UpdatePostTitleAsync(
        BlogContext blogContext,
        int postId,
        string newTitle,
        CancellationToken cancellationToken)
    {
        var postQuery =
            from post in blogContext.Posts
            where post.Id == postId
            select post;

        var matchingPost = await postQuery.FirstOrDefaultAsync(cancellationToken);
        if (matchingPost is null)
        {
            return false;
        }

        matchingPost.Title = newTitle;
        await blogContext.SaveChangesAsync(cancellationToken);
        return true;
    }
}
